    await runDataQuery({ rpc } as unknown as SupabaseClient, "select 1 n;", ["transactions"]);
    expect(rpc).toHaveBeenCalledWith("data_query", { p_sql: "select 1 n;", p_scopes: ["transactions"], p_max_rows: 500 });
